package cl.skinspad.reporte.soporte;
import java.util.*;import java.math.*;import java.time.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static cl.skinspad.reporte.soporte.SoporteDtos.*;
@Service @RequiredArgsConstructor public class PrecioService {
 private final SoporteCatalogoClient catalogo;private final AlertaPrecioRepository alertas;private final SoporteRegistro registro;
 @org.springframework.beans.factory.annotation.Value("${soporte.precio-minimo:5}") private int minimo;
 @org.springframework.beans.factory.annotation.Value("${soporte.precio-superior:3}") private BigDecimal superior;
 @org.springframework.beans.factory.annotation.Value("${soporte.precio-inferior:0.3}") private BigDecimal inferior;
 public AlertaVista vista(AlertaPrecio a){return new AlertaVista(a.getProductoId(),a.getVersion(),a.getNombre(),a.getEstado(),a.getPrecio(),a.getMediana(),a.getComparables(),a.getExplicacion());}
 public List<AlertaVista> pendientes(){return alertas.findAll().stream().filter(a->"PENDIENTE".equals(a.getEstado())).map(this::vista).toList();}
 public AlertaVista contexto(Long id){var lista=catalogo.listar();var p=lista.stream().filter(x->id.equals(x.id())).findFirst().orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Publicación no encontrada"));var actual=PrecioAtipico.calcular(p,lista,minimo,superior,inferior);var existente=alertas.findById(id);String estado=existente.filter(a->PrecioAtipico.huella(p).equals(a.getHuellaValidada())).isPresent()?"VALIDADA":actual.estado();return new AlertaVista(id,existente.map(AlertaPrecio::getVersion).orElse(0L),p.nombre(),estado,p.precio(),actual.mediana(),actual.comparables(),actual.explicacion());}
 @Transactional public void analizar(){var datos=catalogo.listar();for(var p:datos){var calculo=PrecioAtipico.calcular(p,datos,minimo,superior,inferior);var previo=alertas.findById(p.id());if(previo.isEmpty()&&!"PENDIENTE".equals(calculo.estado()))continue;var a=previo.orElseGet(AlertaPrecio::new);String huella=PrecioAtipico.huella(p);a.setProductoId(p.id());a.setHuella(huella);a.setNombre(p.nombre());a.setPrecio(p.precio());a.setMediana(calculo.mediana());a.setComparables(calculo.comparables());a.setExplicacion(calculo.explicacion());a.setEstado(huella.equals(a.getHuellaValidada())?"VALIDADA":calculo.estado());a.setActualizada(Instant.now());alertas.save(a);if("PENDIENTE".equals(a.getEstado()))registro.avisar("PRECIO-"+p.id()+"-"+huella,"ADMIN","Precio atípico pendiente de revisión","/admin/soporte?precios=1");}
  Set<Long> ids=datos.stream().map(SoporteCatalogoClient.Publicacion::id).collect(java.util.stream.Collectors.toSet());for(var a:alertas.findAll())if(!ids.contains(a.getProductoId()))a.setEstado("INACTIVA");
 }
 @Transactional public AlertaVista validar(Long id,ValidarPrecio r,String actor){var a=alertas.bloquear(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Alerta no encontrada"));ValidacionSoporte.version(r.version(),a.getVersion());if(!Boolean.TRUE.equals(r.confirmado()))throw new IllegalArgumentException("Confirma la revisión");String m=ValidacionSoporte.texto(r.motivo(),1000);if(!PrecioAtipico.huella(catalogo.obtener(id)).equals(a.getHuella()))throw new IllegalStateException("La publicación cambió; actualiza el análisis antes de revisarla");if(!"VALIDADA".equals(a.getEstado())){registro.evento("PRECIO",id,actor,"VALIDAR",a.getEstado(),"VALIDADA",m);a.setEstado("VALIDADA");a.setHuellaValidada(a.getHuella());a.setAdminId(actor);a.setMotivoRevision(m);a.setFechaRevision(Instant.now());alertas.flush();}return vista(a);}
}
